24	/**
25	 * 日计划与占用的 JDBC 持久化。所有时刻以 UTC 毫秒存储，时区无关。
26	 */
27	@Repository
28	public class PlanRepository {
29	
30	    private static final RowMapper<DayPlan> PLAN_MAPPER = (rs, n) -> new DayPlan(
31	            rs.getLong("id"),
32	            rs.getString("schedule_key"),
33	            rs.getObject("op_date", LocalDate.class),
34	            rs.getInt("version"),
35	            PlanStatus.valueOf(rs.getString("status")));
