26	 */
27	@SpringBootTest
28	@AutoConfigureMockMvc
29	class PlanApiTest {
30	
31	    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
32	    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
33	
34	    @Autowired
35	    private MockMvc mvc;
36	
37	    @Autowired
38	    private ObjectMapper objectMapper;
39	
40	    // ---------- 主流程 ----------
41	
42	    @Test
43	    void createDraftThenGetDetail() throws Exception {
44	        String scheduleKey = key("SCH");
45	        MvcResult created = mvc.perform(post("/api/v1/plans")
46	                        .contentType(MediaType.APPLICATION_JSON)
47	                        .content(createBody(key("REQ"), scheduleKey,
48	                                occ("G1", key("SEC"), iso(8), iso(9)),
49	                                occ("G2", key("SEC"), iso(9), iso(10)))))
50	                .andExpect(status().isCreated())
51	                .andReturn();
52	        JsonNode body = read(created);
53	        assertThat(body.get("scheduleKey").asText()).isEqualTo(scheduleKey);
54	        assertThat(body.get("version").asInt()).isEqualTo(1);
55	        assertThat(body.get("status").asText()).isEqualTo("DRAFT");
56	        assertThat(body.get("occupancies")).hasSize(2);
57	        assertThat(body.get("occupancies").get(0).get("startUtc").asText())
58	                .isEqualTo(iso(8));
59	
60	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", scheduleKey))
61	                .andExpect(status().isOk()).andReturn();
62	        assertThat(read(detail)).isEqualTo(body);
63	    }
64	
65	    @Test
66	    void updateReplaceOccupanciesIncrementsVersion() throws Exception {
67	        String scheduleKey = key("SCH");
68	        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));
69	
70	        MvcResult updated = mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
71	                        .contentType(MediaType.APPLICATION_JSON)
72	                        .content(updateBody(key("REQ"), 1,
73	                                occ("G3", key("SEC"), iso(10), iso(11)))))
74	                .andExpect(status().isOk()).andReturn();
75	        JsonNode body = read(updated);
76	        assertThat(body.get("version").asInt()).isEqualTo(2);
77	        assertThat(body.get("occupancies")).hasSize(1);
78	        assertThat(body.get("occupancies").get(0).get("trainNo").asText()).isEqualTo("G3");
79	    }
80	
81	    @Test
82	    void publishThenQueryPublishedSlots() throws Exception {
83	        String section = key("SEC");
84	        String scheduleKey = key("SCH");
85	        createPlan(scheduleKey, occ("G1", section, iso(8), iso(9)));
86	        publishPlan(scheduleKey, key("REQ"));
87	
88	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", scheduleKey))
89	                .andExpect(status().isOk()).andReturn();
90	        assertThat(read(detail).get("status").asText()).isEqualTo("PUBLISHED");
91	
92	        MvcResult slots = mvc.perform(get("/api/v1/published-slots")
93	                        .param("date", DAY.toString()).param("sectionId", section))
94	                .andExpect(status().isOk()).andReturn();
95	        JsonNode slotList = read(slots);
96	        assertThat(slotList).hasSize(1);
97	        assertThat(slotList.get(0).get("scheduleKey").asText()).isEqualTo(scheduleKey);
98	        assertThat(slotList.get(0).get("trainNo").asText()).isEqualTo("G1");
99	    }
100	
101	    @Test
102	    void cancelReleasesSlotsAndKeepsHistory() throws Exception {
103	        String section = key("SEC");
104	        String released = key("SCH");
105	        createPlan(released, occ("G1", section, iso(8), iso(9)));
106	        publishPlan(released, key("REQ"));
107	
108	        mvc.perform(post("/api/v1/plans/{key}/cancel", released)
109	                        .contentType(MediaType.APPLICATION_JSON)
110	                        .content(actionBody(key("REQ"))))
111	                .andExpect(status().isOk());
112	
113	        // 历史计划与原始占用保留
114	        MvcResult detail = mvc.perform(get("/api/v1/plans/{key}", released))
115	                .andExpect(status().isOk()).andReturn();
116	        JsonNode body = read(detail);
117	        assertThat(body.get("status").asText()).isEqualTo("CANCELLED");
118	        assertThat(body.get("occupancies")).hasSize(1);
119	
120	        // 时隙已释放：查询为空，且新计划可发布重叠区间
121	        MvcResult slots = mvc.perform(get("/api/v1/published-slots")
122	                        .param("date", DAY.toString()).param("sectionId", section))
123	                .andExpect(status().isOk()).andReturn();
124	        assertThat(read(slots)).isEmpty();
125	
126	        String follower = key("SCH");
127	        createPlan(follower, occ("G9", section, iso(8), iso(9)));
128	        publishPlan(follower, key("REQ"));
129	    }
