    List<PublishedSlot> published = planRepo.findPublishedSlots(plan.opDate(), sectionIds, excludePlanIds);
    List<Map<String, Object>> conflicts = new ArrayList<>();
    // group by section
    for each sectionId in sectionIds:
        List<SlotView> merged = candidate occupancies on section + published slots on section
        SectionConfig cfg = configs.get(sectionId);
        if (cfg == null) {
            // 原互斥：候选 vs 已发布 overlap (保持原行为)
            for candidate o: for slot in published-on-section: overlap -> SECTION_CONFLICT
        } else {
            // 方向必填
            for each entry in merged: direction == null -> DIRECTION_MISSING detail
            if any missing, continue (skip further checks for this section? or still check?) — collect and continue to avoid noise
            // 合并排序，相邻对检查
            sort merged by startUtc
            for adjacent pairs (prev, cur):
                overlap = cur.start < prev.end -> SECTION_CONFLICT (regardless of direction)
                else if prev.direction != cur.direction:
                    gapSeconds = (cur.start - prev.end)/1000  (millis)
                    if gap < cfg.clearanceSeconds -> CLEARANCE_INSUFFICIENT detail with actualSeconds, requiredSeconds
        }
}
